const raw = $input.item.json;
const agentOut = raw.output ?? raw;
const steps = raw.intermediateSteps || [];

const readUrls = new Set();
for (const step of steps) {
  const action = step && step.action;
  if (action && action.tool === 'Read_Page' && action.toolInput && action.toolInput.url) {
    readUrls.add(action.toolInput.url);
  }
}

const cfg = $('Config').item.json;

return [{
  json: {
    ollama_base_url: cfg.ollama_base_url,
    writer_model: cfg.writer_model,
    qa_model: cfg.qa_model,
    qa_min_confidence: cfg.qa_min_confidence,
    research: agentOut,
    verified_read_urls: Array.from(readUrls)
  }
}];

const cfg = $input.item.json;
const research = cfg.research;

const system_prompt = `You are an evidence-based, SEO-aware product review writer for an affiliate review blog.

Your job is to transform VERIFIED PRODUCT RESEARCH into a useful, accurate, search-optimized product review that genuinely helps someone decide whether to buy.

STRICT CONTENT RULES:
1. Use ONLY information supplied in the research data.
2. Do not invent specifications, features, prices, test results, experiences, opinions, or alternative products.
3. Do not claim that you personally tested or used the product.
4. Do not say "we tested" unless the supplied evidence explicitly states our organization performed the test.
5. Do not convert manufacturer claims into independently verified facts.
6. Clearly distinguish: manufacturer claims, independent testing, owner/user opinions.
7. If evidence is conflicting, acknowledge the conflict.
8. If there is insufficient evidence for a claim, do not make the claim.
9. Do not fabricate citations or evidence IDs - every evidence_ids entry in a section or FAQ answer MUST be one of the ids supplied in the research data below.
10. Do not mention information that is not supported by the input.
11. Some independent-test evidence may be drawn from a closely related sibling model rather than the exact product being reviewed (this will be stated in that evidence item's source). When you use such evidence, say so in the text explicitly.
12. When owner sentiment is based on very few reports (check the research data - if there is only one or two owner_sentiment items on a topic), phrase it as an individual report ("one owner reported...") rather than a generalization ("customers report...", "many users say...", "buyers love..."). Never generalize a single anecdote into a broad claim.

SEO AND STRUCTURE RULES:
13. Write "seo_title": a concise, keyword-rich title that includes the exact product name and the word "Review", 60 characters or fewer.
14. Write "meta_description": a compelling search-snippet summary, 150-160 characters, including the product name and its primary use case.
15. Write "best_for" and "not_best_for": one sentence each, describing the ideal buyer and who should skip this product, grounded only in supplied evidence.
16. Write a "faq" array of 3 to 5 realistic buyer questions with answers. Answer ONLY using facts already present in the supplied evidence, and cite evidence_ids the same way as in "sections". If you lack evidence to answer a common buyer question, do not include that question.
17. Write an "alternatives" array using ONLY the alternative products supplied in the research data's "alternatives" field - never invent alternative products. For each, give a one-sentence reason someone might choose it instead, and its evidence_ids where applicable (use an empty array if the research item had no evidence id, since alternatives are supplied directly, not id-tagged - just omit evidence_ids requirement for this field).
18. Your "verdict" must give a clear, decisive recommendation grounded in the evidence (e.g. "Buy this if you need X. Skip it if you need Y."). Do NOT use vague hedging phrases such as "may want to consider", "could be a good option", "worth considering", "appears to be", "seems to be", "might be a good fit".
19. Never write an evidence id (e.g. "EXP-001", "FACT-002", "SENT-003") directly inside reader-facing prose - not in pros, cons, summary, verdict, best_for, not_best_for, or section/FAQ body text. Evidence ids belong ONLY in the dedicated evidence_ids arrays. Readers should never see a bracketed id like "[EXP-001]" on the page.

SCORING ("score" field, a number from 0-10):
There was previously no guidance at all for this field, and it showed - real published reviews came out scoring 0.9 and 4.0-4.5 for products (a well-regarded mechanical keyboard, flagship earbuds) with mostly positive evidence, because the model had no anchor and defaulted to grading harshly. Use this scale:
- 9-10: exceptional, standout in its category, evidence shows few or no meaningful flaws.
- 7-8: strong recommendation, does its job well, only minor/niche caveats.
- 5-6: solid and usable, but with real trade-offs a buyer should know about.
- 3-4: below average, notable flaws outweigh the strengths in the evidence.
- 0-2: reserve for products the evidence shows are seriously broken, unsafe, or not fit for purpose - this should be rare.
The presence of SOME cons is normal and does not by itself justify a low score - nearly every real product has cons. Base the score on the overall balance of verified facts, expert findings, and owner sentiment: if that balance is mostly positive with only minor caveats, score it 7 or higher. Do not average "number of pros vs number of cons" as if they were equally weighted evidence.

VOICE - EDITORIAL 'WE' VOICE, WRITTEN LIKE A REAL PERSON, NOT AN AI:
- Write in first-person-plural editorial voice throughout: 'we found', 'our take', 'we'd recommend', 'in our research'. This 'we' is the editorial team synthesizing the evidence below - it never means you personally tested or used the product. Never write 'we tested', 'we tried', or 'in our testing' unless the supplied evidence explicitly states our organization performed that test.
- Attribute expert findings and owner sentiment to their real source in the prose (e.g. 'One long-term owner on [source] said...', 'Testing by [source] found...'), instead of presenting evidence as an anonymous fact. Never invent a name or outlet not in the supplied evidence. When sentiment rests on only one or two reports, phrase it as an individual report rather than a broad generalization.
- BANNED WORDS AND PHRASES - never use any of these AI-review cliches: boasts, elevate, seamless, seamlessly, game-changer, game changer, unparalleled, unleash, dive into, delve into, navigate the, landscape (as in 'the smartphone landscape'), realm, testament to, plethora, myriad, robust, cutting-edge, revolutionize, revolutionary, 'whether you're a beginner or a pro' or any 'whether you're X or Y' construction, at the end of the day, 'in today's fast-paced world' or any 'in today's ... world' construction, in conclusion, it's important to note that, it's worth noting that, that being said, needless to say, look no further, packed with features, stands out from the competition, sets it apart, a true testament, 'when it comes to' as a section opener.
- BANNED STRUCTURE - never open the review or any section with a rhetorical question. Never open with 'Let's dive in' or 'Let's take a look'. Never end a section with a paragraph that starts 'Overall,'. Do not open more than one section with the same sentence template (e.g. do not start every section with 'The [product] offers...' or 'One of the standout features is...').
- Vary sentence length and rhythm on purpose - mix short, blunt sentences with longer ones. Do not use the same X, Y, and Z three-item list construction in almost every paragraph.
- Every sentence must carry real, specific information from the evidence, not vague praise or padding. If a sentence could apply to any product in the category, cut it or make it specific.
- Confident does NOT mean comparative or superlative. Never write 'the biggest', 'the largest', 'the best', 'the first', 'the only', or any other superlative/comparative claim (e.g. 'the biggest phone Samsung shipped that year', 'the largest display in the lineup') unless a supplied evidence item explicitly states that exact comparison. State the single fact confidently instead (e.g. 'the display is 6.9 inches at 120Hz') rather than inventing an unstated ranking.
- Never generalize a single-source citation into a plural ('owners say', 'buyers report', 'a feature that disappeared from later phones') - if only one evidence item supports a point, say 'one owner reported' every time it comes up, not just on first mention.
- Never state a specific number, limit, or capacity beyond what the evidence actually gives (e.g. if an owner report mentions using a 1TB card, do not state that as the device's maximum supported capacity unless a source says so).

The final output MUST be valid JSON matching the requested schema. Do not output Markdown. Do not output explanations outside the JSON.`;

const user_prompt = `Create a product review from the following verified research.

PRODUCT:
${JSON.stringify(research.product)}

VERIFIED FACTS:
${JSON.stringify(research.facts)}

EXPERT FINDINGS:
${JSON.stringify(research.expert_findings)}

OWNER SENTIMENT:
${JSON.stringify(research.owner_sentiment)}

REAL ALTERNATIVE PRODUCTS (use only these, do not invent others):
${JSON.stringify(research.alternatives)}

Return the review using the exact JSON schema provided in the format parameter.`;

const review_schema = {
  type: "object",
  properties: {
    seo_title: { type: "string" },
    meta_description: { type: "string" },
    title: { type: "string" },
    summary: { type: "string" },
    score: { type: "number" },
    best_for: { type: "string" },
    not_best_for: { type: "string" },
    pros: { type: "array", items: { type: "string" } },
    cons: { type: "array", items: { type: "string" } },
    expert_consensus: { type: "string" },
    owner_consensus: { type: "string" },
    verdict: { type: "string" },
    sections: {
      type: "array",
      items: {
        type: "object",
        properties: {
          heading: { type: "string" },
          content: { type: "string" },
          evidence_ids: { type: "array", items: { type: "string" } }
        },
        required: ["heading", "content", "evidence_ids"]
      }
    },
    faq: {
      type: "array",
      items: {
        type: "object",
        properties: {
          question: { type: "string" },
          answer: { type: "string" },
          evidence_ids: { type: "array", items: { type: "string" } }
        },
        required: ["question", "answer", "evidence_ids"]
      }
    },
    alternatives: {
      type: "array",
      items: {
        type: "object",
        properties: {
          name: { type: "string" },
          reason: { type: "string" }
        },
        required: ["name", "reason"]
      }
    }
  },
  required: ["seo_title", "meta_description", "title", "summary", "score", "best_for", "not_best_for", "pros", "cons", "verdict", "sections", "faq", "alternatives"]
};

const qa_system_prompt = `You are a strict fact-checking and SEO-quality editor.

Review the generated product review against the supplied evidence.

For every factual claim:
1. Determine whether evidence exists.
2. Determine whether the claim accurately represents the evidence.
3. Detect unsupported claims.
4. Detect invented specifications.
5. Detect invented personal experience.
6. Detect claims that incorrectly present manufacturer statements as independent testing.
7. Detect contradictions.
8. Detect any evidence sourced from a sibling/related model that is presented as if it were tested on the exact product being reviewed, without disclosing the distinction.
9. Detect any case where sentiment based on very few reports (fewer than 3 sources in the evidence) is generalized as if it reflects most/all customers (e.g. "customers report" or "buyers love" when only one or two anecdotes exist in the evidence).
10. Detect vague, hedging verdict language (e.g. "may want to consider", "could be a good option", "worth considering") instead of a clear buy/skip recommendation.
11. Detect any alternative product mentioned that does not appear in the supplied research alternatives list.
12. Detect any FAQ answer not grounded in the supplied evidence.

Return JSON only, matching the requested schema.`;

const qa_schema = {
  type: "object",
  properties: {
    status: { type: "string", enum: ["PASS", "FAIL"] },
    confidence: { type: "number" },
    issues: {
      type: "array",
      items: {
        type: "object",
        properties: {
          type: { type: "string" },
          text: { type: "string" },
          reason: { type: "string" }
        }
      }
    }
  },
  required: ["status", "confidence", "issues"]
};

return [{
  json: {
    ...cfg,
    system_prompt: system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(review_schema)}`,
    user_prompt,
    review_schema,
    qa_system_prompt: qa_system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(qa_schema)}`,
    qa_schema
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';

let review = null;
let parseError = null;
try {
  review = JSON.parse(raw);
} catch (e) {
  parseError = e.message;
}

const prep = $('Prepare Prompts').item.json;

let retryCount = 0;
try {
  retryCount = $('Retry Writer').item.json._retryCount;
} catch (e) {
  retryCount = 0;
}

let qaRetryCount = 0;
try {
  qaRetryCount = $('Retry Writer After QA').item.json._qaRetryCount;
} catch (e) {
  qaRetryCount = 0;
}

return [{
  json: {
    review,
    _parseOk: review !== null,
    _parseError: parseError,
    research: prep.research,
    ollama_base_url: prep.ollama_base_url,
    writer_model: prep.writer_model,
    qa_model: prep.qa_model,
    qa_min_confidence: prep.qa_min_confidence,
    system_prompt: prep.system_prompt,
    user_prompt: prep.user_prompt,
    review_schema: prep.review_schema,
    qa_system_prompt: prep.qa_system_prompt,
    qa_schema: prep.qa_schema,
    _retryCount: retryCount,
    _qaRetryCount: qaRetryCount
  }
}];

const item = $input.item.json;
const errors = [];

if (!item._parseOk) {
  errors.push(`Writer output was not valid JSON: ${item._parseError}`);
}

const review = item.review;
const required = ["seo_title", "meta_description", "title", "summary", "pros", "cons", "verdict", "sections", "faq", "alternatives", "best_for", "not_best_for"];

if (review) {
  for (const field of required) {
    if (!(field in review)) errors.push(`Missing field: ${field}`);
  }
  if (review.pros && !Array.isArray(review.pros)) errors.push("pros must be an array");
  if (review.cons && !Array.isArray(review.cons)) errors.push("cons must be an array");
  if ("score" in review && typeof review.score !== "number") errors.push("score must be numeric");

  if (review.seo_title && review.seo_title.length > 60) {
    errors.push(`seo_title is ${review.seo_title.length} chars, must be 60 or fewer`);
  }
  if (review.meta_description && (review.meta_description.length > 160 || review.meta_description.length < 100)) {
    errors.push(`meta_description is ${review.meta_description.length} chars, must be roughly 100-160`);
  }
  if (Array.isArray(review.faq) && review.faq.length < 3) {
    errors.push(`faq has only ${review.faq.length} entries, need at least 3`);
  }
  if (Array.isArray(review.alternatives) && review.alternatives.length < 2) {
    errors.push(`alternatives has only ${review.alternatives.length} entries, need at least 2`);
  }

  const hedgePhrases = ["may want to consider", "could be a good option", "worth considering", "appears to be", "seems to be", "might be a good fit", "might be worth"];
  const verdictLower = (review.verdict || "").toLowerCase();
  for (const phrase of hedgePhrases) {
    if (verdictLower.includes(phrase)) {
      errors.push(`verdict uses hedging language ("${phrase}") instead of a decisive recommendation`);
    }
  }

  const validIds = new Set([
    ...item.research.facts.map(f => f.id),
    ...item.research.expert_findings.map(f => f.id),
    ...item.research.owner_sentiment.map(f => f.id)
  ]);

  if (Array.isArray(review.sections)) {
    for (const section of review.sections) {
      for (const evidenceId of (section.evidence_ids || [])) {
        if (!validIds.has(evidenceId)) {
          errors.push(`Section "${section.heading}" cites unknown evidence id: ${evidenceId}`);
        }
      }
    }
  }

  if (Array.isArray(review.faq)) {
    for (const qa of review.faq) {
      for (const evidenceId of (qa.evidence_ids || [])) {
        if (!validIds.has(evidenceId)) {
          errors.push(`FAQ "${qa.question}" cites unknown evidence id: ${evidenceId}`);
        }
      }
    }
  }

  if (Array.isArray(review.alternatives)) {
    const realNames = new Set((item.research.alternatives || []).map(a => a.name.toLowerCase()));
    for (const alt of review.alternatives) {
      if (!realNames.has((alt.name || "").toLowerCase())) {
        errors.push(`Alternative "${alt.name}" is not in the supplied research alternatives list (possibly invented)`);
      }
    }
  }
}

return [{
  json: {
    ...item,
    _valid: errors.length === 0,
    _errors: errors
  }
}];

const item = $input.item.json;

const feedback = `\n\nYour previous output failed validation for these reasons:\n${item._errors.map(e => `- ${e}`).join('\n')}\n\nFix these issues and return corrected JSON that strictly matches the schema and only cites evidence ids that were supplied.`;

return [{
  json: {
    ollama_base_url: item.ollama_base_url,
    writer_model: item.writer_model,
    qa_model: item.qa_model,
    qa_min_confidence: item.qa_min_confidence,
    system_prompt: item.system_prompt,
    user_prompt: item.user_prompt + feedback,
    review_schema: item.review_schema,
    qa_system_prompt: item.qa_system_prompt,
    qa_schema: item.qa_schema,
    research: item.research,
    _retryCount: (item._retryCount || 0) + 1
  }
}];

const item = $input.item.json;

const qa_user_prompt = `REVIEW TO CHECK:\n${JSON.stringify(item.review)}\n\nSUPPLIED EVIDENCE:\n${JSON.stringify(item.research)}\n\nCheck the review above against the supplied evidence and return your JSON verdict.`;

return [{
  json: {
    ollama_base_url: item.ollama_base_url,
    qa_model: item.qa_model,
    qa_system_prompt: item.qa_system_prompt,
    qa_user_prompt,
    qa_schema: item.qa_schema,
    qa_min_confidence: item.qa_min_confidence,
    review: item.review,
    research: item.research,
    _qaRetryCount: item._qaRetryCount
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';

let qa = null;
let parseError = null;
try {
  qa = JSON.parse(raw);
} catch (e) {
  parseError = e.message;
}

const prep = $('Prepare QA Prompt').item.json;

return [{
  json: {
    qa,
    _qaParseOk: qa !== null,
    _qaParseError: parseError,
    review: prep.review,
    research: prep.research,
    qa_min_confidence: prep.qa_min_confidence,
    _qaRetryCount: prep._qaRetryCount || 0
  }
}];

const item = $input.item.json;
const prep = $('Prepare Prompts').item.json;

const issues = (item.qa && item.qa.issues) || [];
const issuesText = issues.map(i => `- [${i.type}] "${i.text}" - ${i.reason}`).join('\n');

const feedback = `\n\nA strict fact-checking editor reviewed your previous draft against the supplied evidence and rejected it (status: ${item.qa && item.qa.status}, confidence: ${item.qa && item.qa.confidence}, minimum required: ${item.qa_min_confidence}). Issues found:\n${issuesText}\n\nRewrite the full review to fix every issue above. Do not overstate, generalize beyond, or misrepresent what the supplied evidence actually shows - if evidence only gives raw numbers with no comparison, do not call it 'class-leading' or 'top of the class'; if a claim is based on fewer than three sources, phrase it as an individual report, not a general consensus. Keep everything else about the review that was not flagged as an issue.`;

return [{
  json: {
    ollama_base_url: prep.ollama_base_url,
    writer_model: prep.writer_model,
    qa_model: prep.qa_model,
    qa_min_confidence: prep.qa_min_confidence,
    system_prompt: prep.system_prompt,
    user_prompt: prep.user_prompt + feedback,
    review_schema: prep.review_schema,
    qa_system_prompt: prep.qa_system_prompt,
    qa_schema: prep.qa_schema,
    research: prep.research,
    _qaRetryCount: (item._qaRetryCount || 0) + 1
  }
}];

const item = $input.item.json;

const approved = {
  ...item.review,
  qa: item.qa,
  approved_at: new Date().toISOString(),
  product: item.research.product
};

return [{ json: approved }];

const item = $input.item.json;
const errors = [];

if (!item._parseOk || !item.research) {
  errors.push(`Research extraction output was not valid JSON: ${item._parseError}`);
  return [{ json: { ...item, _research_trust_valid: false, _research_trust_errors: errors } }];
}

const research = item.research;
const verifiedUrls = new Set(item.verified_read_urls || []);

function hostnameOf(url) {
  try { const m = String(url).match(/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\/(?:[^@/]+@)?([^/:?#]+)/); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; } catch (e) { return ''; }
}

const brandHost = hostnameOf((research.facts && research.facts[0] && research.facts[0].source_url) || '');

const allEvidence = [
  ...(research.facts || []),
  ...(research.expert_findings || []),
  ...(research.owner_sentiment || [])
];

for (const ev of allEvidence) {
  if (!ev.source_url) {
    errors.push(`Evidence ${ev.id} has no source_url`);
  } else if (!verifiedUrls.has(ev.source_url)) {
    errors.push(`Evidence ${ev.id} cites ${ev.source_url} but that page was never actually fetched - not acceptable evidence`);
  }
}

const independentReads = (research.expert_findings || []).filter(f =>
  f.type === 'independent_test' &&
  f.source_url && verifiedUrls.has(f.source_url) &&
  hostnameOf(f.source_url) !== brandHost
);

if (independentReads.length === 0) {
  errors.push('No genuinely independent (non-manufacturer-domain) expert finding was found AND actually fetched. At least one is required before this product can be reviewed.');
}

if (!research.alternatives || research.alternatives.length < 2) {
  errors.push('Research must include at least 2 real alternative products.');
}

return [{
  json: {
    ...item,
    _research_trust_valid: errors.length === 0,
    _research_trust_errors: errors
  }
}];

const cfg = $input.item.json;
const productName = cfg.product_name;

const queries = {
  specs: `${productName} official specifications`,
  independent: `${productName} independent expert review`,
  owner: `${productName} owner reviews customer experience`,
  alternatives: `${productName} alternatives comparison vs`
};

const searches = {};
for (const [key, q] of Object.entries(queries)) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://searxng:8080/search',
      qs: { format: 'json', language: 'en', q },
      json: true
    });
    searches[key] = (res.results || []).slice(0, 6).map(r => ({ title: r.title, url: r.url, content: r.content }));
  } catch (e) {
    searches[key] = [];
  }
}

return [{
  json: {
    ...cfg,
    searches
  }
}];

const cfg = $input.item.json;

const choose_system_prompt = `You are a research assistant choosing which real search results are worth reading in full to research a product.

You will be given search results grouped into 4 categories:
- specs: official manufacturer specifications
- independent: an independent/expert review (must NOT be the manufacturer's own website)
- owner: owner/customer reviews
- alternatives: competing products

Rules:
1. For 'independent', you MUST pick a URL whose domain is different from the official manufacturer's domain (the manufacturer's domain will be visible in the 'specs' results).
2. For each category, pick the single best, most relevant, most trustworthy URL from the results ACTUALLY PROVIDED - never invent a URL not present in the given results.
3. NEVER pick a URL ending in .pdf, or any URL that is obviously a PDF/binary document - those cannot be read as text. Always prefer a normal HTML web page.
4. If a category truly has no usable (non-PDF) results, omit it from your picks.
5. For 'specs', 'owner' and 'alternatives', you may pick up to 2 URLs (a primary and a backup) in case one fails to load. For 'independent', pick up to 3 URLs (a primary and two backups) - independent review sites are especially prone to membership walls, paywalls and JS-only content that leaves no usable text once fetched, so give yourself more chances to land on one that actually works.
6. You MUST include at least one pick for EACH of the four categories (specs, independent, owner, alternatives) as long as that category has at least one non-PDF result available. Do not skip a category just because another category seems more interesting.
7. Output JSON only: {"picks": [{"category": "...", "url": "...", "why": "..."}]}`;

const choose_user_prompt = `Product: ${cfg.product_name} (${cfg.brand}, ${cfg.category})

SEARCH RESULTS BY CATEGORY:
${JSON.stringify(cfg.searches)}

Pick the URLs worth reading in full.`;

const choose_schema = {"type": "object", "properties": {"picks": {"type": "array", "items": {"type": "object", "properties": {"category": {"type": "string", "enum": ["specs", "independent", "owner", "alternatives"]}, "url": {"type": "string"}, "why": {"type": "string"}}, "required": ["category", "url", "why"]}}}, "required": ["picks"]};

return [{
  json: {
    ...cfg,
    choose_system_prompt: choose_system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(choose_schema)}`,
    choose_user_prompt,
    choose_schema
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';
let parsed = null, parseError = null;
try { parsed = JSON.parse(raw); } catch (e) { parseError = e.message; }

const prep = $('Prepare Choose Prompt').item.json;
let _researchRetryCount = 0;
try { _researchRetryCount = $('Retry Choose Sources').item.json._researchRetryCount || 0; } catch (e) { _researchRetryCount = 0; }

return [{
  json: {
    ollama_base_url: prep.ollama_base_url,
    research_model: prep.research_model,
    writer_model: prep.writer_model,
    qa_model: prep.qa_model,
    qa_min_confidence: prep.qa_min_confidence,
    product_name: prep.product_name,
    brand: prep.brand,
    category: prep.category,
    picks: (parsed && parsed.picks) || [],
    _chooseParseError: parseError,
    _researchRetryCount
  }
}];

const item = $input.item.json;
const picks = item.picks || [];
const pages = [];
const productName = (item.product_name || '').toLowerCase();

function extractRelevantWindow(text, keyword, windowSize) {
  if (!keyword) return text.slice(0, windowSize);
  const lower = text.toLowerCase();
  const idx = lower.indexOf(keyword);
  if (idx === -1) return text.slice(0, windowSize);
  const start = Math.max(0, idx - Math.floor(windowSize * 0.25));
  return text.slice(start, start + windowSize);
}

for (const pick of picks) {
  try {
    const html = await this.helpers.httpRequest({
      method: 'GET',
      url: pick.url,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36' }
    });
    const cleaned = String(html)
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<!--[\s\S]*?-->/g, ' ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;|&amp;|&quot;|&#39;/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    const text = extractRelevantWindow(cleaned, productName, 7000);
    pages.push({ category: pick.category, url: pick.url, why: pick.why, text });
  } catch (e) {
    pages.push({ category: pick.category, url: pick.url, why: pick.why, text: `[failed to fetch: ${e.message}]` });
  }
}

return [{
  json: {
    ...item,
    fetched_pages: pages,
    verified_read_urls: pages.filter(p => !p.text.startsWith('[failed')).map(p => p.url)
  }
}];

const item = $input.item.json;

const extract_system_prompt = `You are a product research data extractor. You will be given the ACTUAL TEXT content of several real web pages that were already fetched for you (each labeled with its category and source_url), plus the product's name/brand/category.

Your job: extract ONLY real, verifiable evidence from the text you were given. Never invent facts, numbers, quotes, or URLs, and never use information not present in the provided page text. If a page's text looks like binary/garbage data (e.g. starts with %PDF or is unreadable symbols) or says "[failed to fetch...]", treat that category as having no usable evidence - return an empty array for it, do not guess.

Rules:
