   Example of a correctly formatted item: {"id": "SENT-001", "topic": "durability", "sentiment": "negative", "detail": "...", "source_name": "ProductReview.com.au", "source_url": "https://www.productreview.com.au/listings/example"}
6. If a category's page text is empty, marked failed, unreadable, or has no relevant information, return an empty array for that category.
7. Do not fabricate anything not present in the given text.
8. Output JSON only, matching the required schema.`;

const pageBlocks = (item.fetched_pages || []).map(p =>
  `--- CATEGORY: ${p.category} | SOURCE_URL: ${p.url} ---\n${p.text}`
).join('\n\n');

const extract_user_prompt = `PRODUCT: ${JSON.stringify({ name: item.product_name, brand: item.brand, category: item.category })}

FETCHED PAGE CONTENT:
${pageBlocks}

Extract the structured research JSON from the above.`;

const research_schema = {"type": "object", "properties": {"product": {"type": "object", "properties": {"name": {"type": "string"}, "brand": {"type": "string"}, "category": {"type": "string"}, "model": {"type": "string"}}, "required": ["name", "brand", "category", "model"]}, "facts": {"type": "array", "items": {"type": "object", "properties": {"id": {"type": "string"}, "claim": {"type": "string"}, "source_name": {"type": "string"}, "source_url": {"type": "string"}, "type": {"type": "string", "enum": ["manufacturer_claim"]}}, "required": ["id", "claim", "source_name", "source_url", "type"]}}, "expert_findings": {"type": "array", "items": {"type": "object", "properties": {"id": {"type": "string"}, "finding": {"type": "string"}, "source_name": {"type": "string"}, "source_url": {"type": "string"}, "type": {"type": "string", "enum": ["independent_test"]}}, "required": ["id", "finding", "source_name", "source_url", "type"]}}, "owner_sentiment": {"type": "array", "items": {"type": "object", "properties": {"id": {"type": "string"}, "topic": {"type": "string"}, "sentiment": {"type": "string"}, "detail": {"type": "string"}, "source_name": {"type": "string"}, "source_url": {"type": "string"}}, "required": ["id", "topic", "sentiment", "detail", "source_name", "source_url"]}}, "alternatives": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "reason": {"type": "string"}, "source_url": {"type": "string"}}, "required": ["name", "reason", "source_url"]}}}, "required": ["product", "facts", "expert_findings", "owner_sentiment", "alternatives"]};

return [{
  json: {
    ...item,
    extract_system_prompt: extract_system_prompt + `\n\nReturn ONLY a JSON object matching exactly this schema - no markdown fences, no extra commentary:\n${JSON.stringify(research_schema)}`,
    extract_user_prompt,
    research_schema
  }
}];

const res = $input.item.json;
const raw = (res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content) || (res.message && res.message.content) || res.response || '';
let research = null, parseError = null;
try { research = JSON.parse(raw); } catch (e) { parseError = e.message; }

